#!/usr/bin/env bash
set -Eeuo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
STATE_DIR="${DETRAN_STACK_STATE_DIR:-${TMPDIR:-/tmp}/detran-stack}"
LOG_DIR="$STATE_DIR/logs"
PID_DIR="$STATE_DIR/pids"
PROXY_CONFIG="$ROOT_DIR/tools/detran-stack.proxy.json"

DB_CONTAINER="${DETRAN_DB_CONTAINER:-detran-postgres-demo}"
DB_IMAGE="${DETRAN_DB_IMAGE:-postgis/postgis@sha256:44126d872ac91993766c341e369c539e8196614321765d36a6f1bab0419a5fa5}"
DB_VOLUME="${DETRAN_DB_VOLUME:-detran-postgres-demo}"
DB_HOST="${DB_HOST:-127.0.0.1}"
DB_PORT="${DB_PORT:-5432}"
DB_USER="${DB_USER:-postgres}"
DB_PASSWORD="${DB_PASSWORD:-postgres}"
DB_NAME="${DB_NAME:-detran_r13}"

MOCK_COMPOSE_FILE="$ROOT_DIR/senatran-mock/docker-compose.yml"
MOCK_PROJECT="${DETRAN_MOCK_PROJECT:-detran-senatran-mock}"
BACKEND_PORT="${DETRAN_BACKEND_PORT:-3001}"

declare -a FRONTEND_NAMES=(portal rait dashboard teat)
declare -a FRONTEND_DIRS=(
  "$ROOT_DIR/apps/portal/web"
  "$ROOT_DIR/apps/rait/web"
  "$ROOT_DIR/apps/dashboard/web"
  "$ROOT_DIR/apps/teat/web"
)
declare -a FRONTEND_PORTS=(4200 4201 4202 4203)
declare -a FRONTEND_PROJECTS=(
  'portal-web'
  'rait-web'
  'dashboard-web'
  'teat-web'
)

mkdir -p "$LOG_DIR" "$PID_DIR"

usage() {
  cat <<'EOF'
Usage: tools/detran-stack.sh <command> [options]

Commands:
  start [--no-mock]  Start database, optional SENATRAN mock, backend and web apps
  stop               Stop only this project's processes and containers
  restart [--no-mock]
  status             Show managed processes, Docker services and URLs
  logs <service>     Follow logs: db|mock|backend|portal|rait|dashboard|teat
  build              Build the backend and its workspace dependencies
  db-init            Apply DDL and the fresh demonstration seed without reset
  db-reset           Recreate disposable DB detran_r13 and apply fresh seed
  help               Show this help

Environment overrides:
  DETRAN_STACK_STATE_DIR, DETRAN_DB_CONTAINER, DETRAN_DB_IMAGE,
  DETRAN_DB_VOLUME, DB_PORT, DB_USER, DB_PASSWORD, DB_NAME,
  DETRAN_BACKEND_PORT, DETRAN_MOCK_PROJECT

The script never removes Docker volumes. Use `db-reset` only for the disposable
DB configured by DB_NAME (default: detran_r13).
EOF
}

die() {
  echo "detran-stack: $*" >&2
  exit 1
}

log() {
  echo "detran-stack: $*"
}

require_command() {
  command -v "$1" >/dev/null 2>&1 || die "command not found: $1"
}

require_runtime() {
  require_command docker
  require_command pnpm
  docker info >/dev/null 2>&1 || die "Docker Desktop is not running or is inaccessible"
}

database_env() {
  printf '%s\n' \
    "DB_HOST=$DB_HOST" \
    "DB_PORT=$DB_PORT" \
    "DB_USER=$DB_USER" \
    "DB_PASSWORD=$DB_PASSWORD" \
    "DB_NAME=$DB_NAME"
}

database_env_array() {
  DATABASE_ENV=(
    "DB_HOST=$DB_HOST"
    "DB_PORT=$DB_PORT"
    "DB_USER=$DB_USER"
    "DB_PASSWORD=$DB_PASSWORD"
    "DB_NAME=$DB_NAME"
  )
}

container_exists() {
  docker inspect "$DB_CONTAINER" >/dev/null 2>&1
}

container_running() {
  [[ "$(docker inspect --format '{{.State.Running}}' "$DB_CONTAINER" 2>/dev/null || true)" == true ]]
}

start_database() {
  if ! container_exists; then
    log "creating PostGIS container $DB_CONTAINER"
    docker volume inspect "$DB_VOLUME" >/dev/null 2>&1 || docker volume create "$DB_VOLUME" >/dev/null
    docker run --detach \
      --name "$DB_CONTAINER" \
      --platform linux/amd64 \
      --env POSTGRES_DB=postgres \
      --env POSTGRES_USER=postgres \
      --env "POSTGRES_PASSWORD=$DB_PASSWORD" \
      --publish "127.0.0.1:$DB_PORT:5432" \
      --volume "$DB_VOLUME:/var/lib/postgresql/data" \
      "$DB_IMAGE" >/dev/null
  elif ! container_running; then
    log "starting existing PostGIS container $DB_CONTAINER"
    docker start "$DB_CONTAINER" >/dev/null
  fi

  for _ in $(seq 1 60); do
    if docker exec "$DB_CONTAINER" pg_isready -U postgres -d postgres >/dev/null 2>&1; then
      return
    fi
    sleep 1
  done
  docker logs --tail 80 "$DB_CONTAINER" >&2 || true
  die "PostGIS did not become ready"
}

database_exists() {
  docker exec "$DB_CONTAINER" psql -X -U postgres -d postgres -Atc \
    "select 1 from pg_database where datname = '$DB_NAME'" 2>/dev/null | grep -qx 1
}

database_roles_exist() {
  docker exec "$DB_CONTAINER" psql -X -U postgres -d "$DB_NAME" -Atc \
    "select count(*) from pg_roles where rolname in ('role_app_backend','role_auditor_min')" 2>/dev/null | grep -qx 2
}

seed_database() {
  database_env_array
  log "applying fresh demonstration seed to $DB_NAME"
  env "${DATABASE_ENV[@]}" SEED_PROFILE=fresh bash "$ROOT_DIR/backend/database/seed.sh"
}

init_database() {
  start_database
  database_env_array
  if ! database_exists || ! database_roles_exist; then
    log "initializing disposable database $DB_NAME"
    env "${DATABASE_ENV[@]}" DETRAN_R13_FULL_AUTHORIZED=1 pnpm --dir "$ROOT_DIR" backend:db:reset
  else
    log "applying current DDL to existing database $DB_NAME"
    env "${DATABASE_ENV[@]}" pnpm --dir "$ROOT_DIR" backend:db:apply
  fi
  seed_database
}

reset_database() {
  [[ "$DB_NAME" == detran_r13 ]] || die "db-reset is restricted to DB_NAME=detran_r13"
  start_database
  database_env_array
  log "resetting disposable database $DB_NAME"
  env "${DATABASE_ENV[@]}" DETRAN_R13_FULL_AUTHORIZED=1 pnpm --dir "$ROOT_DIR" backend:db:reset
  seed_database
}

mock_start() {
  [[ -f "$MOCK_COMPOSE_FILE" ]] || die "missing SENATRAN mock compose file"
  log "starting SENATRAN mock"
  docker compose -p "$MOCK_PROJECT" -f "$MOCK_COMPOSE_FILE" up --build -d
}

mock_stop() {
  docker compose -p "$MOCK_PROJECT" -f "$MOCK_COMPOSE_FILE" down
}

mock_status() {
  docker compose -p "$MOCK_PROJECT" -f "$MOCK_COMPOSE_FILE" ps
}

backend_pid_file() {
  echo "$PID_DIR/backend.pid"
}

frontend_pid_file() {
  echo "$PID_DIR/$1.pid"
}

pid_running() {
  local pid_file="$1"
  [[ -f "$pid_file" ]] || return 1
  local pid
  pid="$(<"$pid_file")"
  [[ "$pid" =~ ^[0-9]+$ ]] && kill -0 "$pid" 2>/dev/null
}

kill_tree() {
  local pid="$1"
  local child
  for child in $(pgrep -P "$pid" 2>/dev/null || true); do
    kill_tree "$child"
  done
  kill "$pid" 2>/dev/null || true
}

stop_pid_file() {
  local pid_file="$1"
  [[ -f "$pid_file" ]] || return 0
  local pid
  pid="$(<"$pid_file")"
  if [[ "$pid" =~ ^[0-9]+$ ]] && kill -0 "$pid" 2>/dev/null; then
    kill_tree "$pid"
    for _ in $(seq 1 30); do
      kill -0 "$pid" 2>/dev/null || break
      sleep 0.2
    done
  fi
  rm -f "$pid_file"
}

start_backend() {
  local pid_file
  pid_file="$(backend_pid_file)"
  pid_running "$pid_file" && { log "backend already running"; return; }
  rm -f "$pid_file"
  log_file="$LOG_DIR/backend.log"
  log "starting backend on http://127.0.0.1:$BACKEND_PORT"
  (
    cd "$ROOT_DIR"
    exec env \
      DETRAN_RUNTIME_PROFILE="${DETRAN_RUNTIME_PROFILE:-local-sandbox}" \
      DETRAN_LOCAL_TENANT_ID="${DETRAN_LOCAL_TENANT_ID:-00000000-0000-7000-8000-00000000a001}" \
      DETRAN_LOCAL_ROLES="${DETRAN_LOCAL_ROLES:-technical-admin,agency-admin,field-agent,rait-coordinator,dash-operator}" \
      DATABASE_URL="postgresql://$DB_USER:$DB_PASSWORD@$DB_HOST:$DB_PORT/$DB_NAME" \
      SENATRAN_PROVIDER="${SENATRAN_PROVIDER:-mock}" \
      SENATRAN_MOCK_BASE_URL="${SENATRAN_MOCK_BASE_URL:-http://127.0.0.1:3000}" \
      PORT="$BACKEND_PORT" \
      pnpm --filter @detran/app start
  ) >"$log_file" 2>&1 &
  echo $! >"$pid_file"
}

start_frontend() {
  local name="$1"
  local directory="$2"
  local port="$3"
  local project_name="$4"
  local pid_file
  pid_file="$(frontend_pid_file "$name")"
  pid_running "$pid_file" && { log "$name frontend already running"; return; }
  rm -f "$pid_file"
  log "starting $name frontend on http://127.0.0.1:$port"
  (
    cd "$directory"
    exec env NG_CLI_ANALYTICS=false pnpm exec ng serve \
      --configuration development \
      --host 127.0.0.1 \
      --port "$port" \
      --proxy-config "$PROXY_CONFIG" \
      "$project_name"
  ) >"$LOG_DIR/$name.log" 2>&1 &
  echo $! >"$pid_file"
}

start_frontends() {
  local index
  for index in "${!FRONTEND_NAMES[@]}"; do
    start_frontend \
      "${FRONTEND_NAMES[$index]}" \
      "${FRONTEND_DIRS[$index]}" \
      "${FRONTEND_PORTS[$index]}" \
      "${FRONTEND_PROJECTS[$index]}"
  done
}

build_stack() {
  log "building backend and workspace dependencies"
  pnpm --dir "$ROOT_DIR" build
}

start_stack() {
  local with_mock=1
  if [[ "${1:-}" == --no-mock ]]; then
    with_mock=0
  elif [[ "${1:-}" != "" ]]; then
    die "unknown start option: $1"
  fi
  require_runtime
  init_database
  [[ -f "$ROOT_DIR/backend/app/dist/main.js" ]] || build_stack
  if [[ "$with_mock" == 1 ]]; then mock_start; fi
  start_backend
  start_frontends
  log "stack started; run '$0 status' for URLs and health"
}

stop_stack() {
  require_runtime
  local index
  for index in "${!FRONTEND_NAMES[@]}"; do
    stop_pid_file "$(frontend_pid_file "${FRONTEND_NAMES[$index]}")"
  done
  stop_pid_file "$(backend_pid_file)"
  mock_stop >/dev/null 2>&1 || true
  if container_running; then
    log "stopping PostGIS container $DB_CONTAINER"
    docker stop "$DB_CONTAINER" >/dev/null
  fi
  log "stack stopped; volumes preserved"
}

status_process() {
  local name="$1"
  local pid_file="$2"
  if pid_running "$pid_file"; then
    echo "$name: running (pid $(<"$pid_file"))"
  else
    echo "$name: stopped"
  fi
}

status_stack() {
  require_runtime
  echo "== detran stack =="
  if container_running; then
    echo "database: running ($DB_CONTAINER, $DB_HOST:$DB_PORT/$DB_NAME)"
  elif container_exists; then
    echo "database: stopped ($DB_CONTAINER)"
  else
    echo "database: not created ($DB_CONTAINER)"
  fi
  status_process backend "$(backend_pid_file)"
  local index
  for index in "${!FRONTEND_NAMES[@]}"; do
    status_process "${FRONTEND_NAMES[$index]}" "$(frontend_pid_file "${FRONTEND_NAMES[$index]}")"
  done
  echo
  echo "== SENATRAN mock =="
  mock_status || true
  echo
  echo "== URLs =="
  echo "backend:  http://127.0.0.1:$BACKEND_PORT/healthz"
  echo "mock:     http://127.0.0.1:3000/health"
  echo "portal:   http://127.0.0.1:4200"
  echo "rait:     http://127.0.0.1:4201"
  echo "dashboard:http://127.0.0.1:4202"
  echo "teat:     http://127.0.0.1:4203"
}

logs_stack() {
{
  "/v1": {
    "target": "http://127.0.0.1:3001",
    "secure": false,
    "changeOrigin": true,
    "ws": true
  }
}
#!/usr/bin/env bash
set -euo pipefail

rait_db_name=${DB_NAME:-detran}
rait_db_host=${DB_HOST:-localhost}
rait_db_port=${DB_PORT:-5432}
rait_db_user=${DB_USER:-postgres}
export PGPASSWORD=${DB_PASSWORD:-}
[[ "$rait_db_name" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || { echo "invalid DB_NAME identifier" >&2; exit 2; }
rait_full=0
for rait_argument in "$@"; do
  case "$rait_argument" in
    --full) rait_full=1 ;;
    *) echo "unknown flag: $rait_argument" >&2; exit 2 ;;
  esac
done
if [[ "$rait_full" = 1 ]]; then
  case "$rait_db_name" in
    detran_r7_ctg1_a2)
      [[ "${DETRAN_PRIORITY_UPGRADE_FULL_AUTHORIZED:-}" = 1 ]] || {
        echo "--full requires explicit disposable detran_r7_ctg1_a2 rehearsal authorization" >&2
        exit 2
      }
      ;;
    detran_r13)
      [[ "${DETRAN_R13_FULL_AUTHORIZED:-}" = 1 ]] || {
        echo "--full requires explicit disposable detran_r13 rehearsal authorization" >&2
        exit 2
      }
      ;;
    *)
      echo "--full is not authorized for database: $rait_db_name" >&2
      exit 2
      ;;
  esac
fi
rait_directory="$(cd "$(dirname "$0")" && pwd)"
# Closed inventory and lexical SQL inspection precede every connection.
# Dollar bodies, quoted literals and nested comments are lexed separately.
read -r -d '' rait_preflight_source <<'NODE' || true
const fs = require('node:fs');
const path = require('node:path');
const dir = process.argv[1];
const full = process.argv[2] === '1';
const ordinary = ["00-extensions.sql","01-schemas.sql","02-auth.sql","03-audit.sql","04-integration-storage.sql","05-role-catalog.sql","10-postgis-functions.sql","11-auth-functions.sql","12-audit-functions.sql","13-ops-agency.sql","13-ops-field-operations.sql","14-inf-lifecycle-vocabulary.sql","15-ops-parameter.sql","16-ops-snapshots.sql","17-ops-evidence.sql","18-ops-offline-sync.sql","19-dashboard-lifecycle-vocabulary.sql","19-est-lifecycle-vocabulary.sql","19-portal-platform.sql","20-rls-policies.sql","21-ops-provisioning.sql","30-inf-normative.sql","30-ops-example.sql","31-inf-ait.sql","32-inf-measures.sql","33-inf-alcohol.sql","34-inf-rait-case.sql","35-inf-rait-worklist.sql","36-inf-rait-session.sql","37-inf-speed.sql","38-inf-infraction.sql","39-inf-rait-org.sql","40-ch-clinical-network.sql","41-ch-patients.sql","42-ch-encounters.sql","43-ch-exams.sql","44-ch-reports.sql","45-ch-biometrics.sql","46-ch-scheduling.sql","47-ch-restrictions.sql","48-ch-retention.sql","49-ch-process-blocks.sql","50-ch-telehealth.sql","51-ch-billing.sql","52-ch-clinical-controls.sql","53-ch-inconsistencies.sql","54-ch-operational-controls.sql","55-ch-juntas.sql","56-ch-toxicology.sql","57-inf-collection.sql","58-inf-rait-integration.sql","59-inf-notification.sql","60-portal-complaints.sql","61-portal-identity.sql","62-portal-requests.sql","63-portal-inbox.sql","64-portal-citizen-service.sql","65-portal-projections.sql","70-est-crash.sql","71-dashboard-crashes.sql","72-integration-renaest-mirror.sql","75-boat-renaest-job.sql","80-dashboard.sql"];
const manual = ['19-rait-priority-pre.sql','19-rait-priority-enforce.sql','19-rait-priority-verify.sql'];
const expected = [...ordinary,...manual].sort();
const present = fs.readdirSync(path.join(dir,'ddl')).filter(n=>n.endsWith('.sql')).sort();
if (JSON.stringify(present)!==JSON.stringify(expected)) throw new Error('Unknown, missing or duplicate DDL inventory');
for (const name of expected) if (!fs.lstatSync(path.join(dir,'ddl',name)).isFile()) throw new Error('DDL must be a regular file: '+name);
function statements(sql) {
  let out=[], text='', i=0;
  while(i<sql.length) {
    if(sql.startsWith('--',i)) { const j=sql.indexOf('\n',i); i=j<0?sql.length:j; text+=' '; continue; }
    if(sql.startsWith('/*',i)) {
      let depth=1;i+=2;
      while(i<sql.length&&depth) {if(sql.startsWith('/*',i)){depth++;i+=2;}else if(sql.startsWith('*/',i)){depth--;i+=2;}else i++;}
      if(depth)throw new Error('Unclosed SQL comment');text+=' ';continue;
    }
    if(sql[i]==="'"||sql[i]==='"') {
      const q=sql[i]; let piece=q;i++;let closed=false;
      while(i<sql.length){const c=sql[i++];piece+=c;if(c===q){if(sql[i]===q){piece+=sql[i++];}else{closed=true;break;}}}
      if(!closed)throw new Error('Unclosed SQL literal');text+=piece;continue;
    }
    const tag=sql.slice(i).match(/^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/);
    if(tag){const end=sql.indexOf(tag[0],i+tag[0].length);if(end<0)throw new Error('Unclosed dollar body');text+=sql.slice(i,end+tag[0].length);i=end+tag[0].length;continue;}
    if(sql[i]==='\\')throw new Error('psql meta commands/includes are forbidden');
    if(sql[i]===';'){if(text.trim())out.push(text.trim());text='';i++;continue;}
    text+=sql[i++];
  }
  if(text.trim())out.push(text.trim());return out;
}
const parsed=new Map();
for(const name of expected){
 const source=fs.readFileSync(path.join(dir,'ddl',name),'utf8');
 const list=statements(source);parsed.set(name,list);
 for(const s of list){
   if(/^(?:BEGIN|START\s+TRANSACTION|COMMIT|END|ROLLBACK|ABORT|VACUUM|CHECKPOINT|DISCARD|COPY|PREPARE\s+TRANSACTION)\b/i.test(s)
     || /^(?:CREATE|DROP)\s+(?:DATABASE|TABLESPACE)\b/i.test(s)
     || /^ALTER\s+SYSTEM\b/i.test(s)
     || /^(?:CREATE|DROP|REINDEX)\s+(?:UNIQUE\s+)?INDEX\s+CONCURRENTLY\b/i.test(s)
     || /^REINDEX\b[\s\S]*\bCONCURRENTLY\b/i.test(s)) throw new Error('Non-transactional or transaction-control statement in '+name);
 }
}
// Compare canonical values before DDL05/14. Never restore/mask a legacy write.
const checks=[];
for(const name of ['05-role-catalog.sql','14-inf-lifecycle-vocabulary.sql']){
 for(const s of parsed.get(name).filter(s=>/^INSERT\s+INTO\b/i.test(s))){
   const m=s.match(/^INSERT\s+INTO\s+([a-z_]+\.[a-z_]+)\s*\(([^)]+)\)\s*VALUES\s+([\s\S]+?)\s+ON\s+CONFLICT\s*\(([^)]+)\)/i);
   if(!m)throw new Error('Unrecognized canonical catalog INSERT in '+name);
   const [,table,columns,values,key]=m;
   if(!/^[a-z_]+$/.test(key.trim()))throw new Error('Unsupported catalog identity');
   const cols=columns.split(',').map(c=>c.trim());
   if(cols.some(c=>!/^[a-z_]+$/.test(c)))throw new Error('Invalid canonical column');
   const comparison=cols.map(c=>"t."+c+"::text IS DISTINCT FROM e."+c+"::text").join(' OR ');
   const query="WITH e("+columns+") AS (VALUES "+values+") SELECT EXISTS(SELECT FROM e LEFT JOIN "+table+" t ON t."+key.trim()+"::text=e."+key.trim()+"::text WHERE t."+key.trim()+" IS NULL OR "+comparison+")";
   checks.push("IF to_regclass('"+table+"') IS NOT NULL THEN EXECUTE 'LOCK TABLE "+table+" IN ACCESS EXCLUSIVE MODE'; EXECUTE "+quote(query)+" INTO divergent; IF divergent THEN RAISE EXCEPTION 'Canonical legacy catalog differs: "+table+"'; END IF; END IF;");
 }
}
if(checks.length!==11)throw new Error('Expected eleven canonical catalog INSERT sources');
function quote(s){return "'"+s.replaceAll("'","''")+"'";}
const validAppRole = "SELECT FROM pg_roles WHERE rolname='role_app_backend' AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcanlogin";
const validAuditorRole = "SELECT FROM pg_roles WHERE rolname='role_auditor_min' AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcanlogin";
const rolePreflight = full
  ? "IF EXISTS(SELECT FROM pg_roles WHERE rolname='role_app_backend') AND NOT EXISTS("+validAppRole+") THEN RAISE EXCEPTION 'Existing operational roles required; global creation not authorized'; END IF; IF EXISTS(SELECT FROM pg_roles WHERE rolname='role_auditor_min') AND NOT EXISTS("+validAuditorRole+") THEN RAISE EXCEPTION 'Existing operational roles required; global creation not authorized'; END IF; "
  : "IF NOT EXISTS("+validAppRole+") OR NOT EXISTS("+validAuditorRole+") THEN RAISE EXCEPTION 'Existing operational roles required; global creation not authorized'; END IF; ";
console.log("SET LOCAL ROLE postgres; SET LOCAL search_path = pg_catalog, public; DO $preflight$ DECLARE r record; divergent boolean; BEGIN "+
rolePreflight+
"FOR r IN SELECT n.nspname,c.relname,c.relowner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops') AND c.relkind IN ('r','p') ORDER BY n.nspname,c.relname LOOP IF r.relowner <> 'postgres'::regrole THEN RAISE EXCEPTION 'Unsupported legacy owner %.%',r.nspname,r.relname; END IF; END LOOP; "+
checks.join(' ')+" END $preflight$;");
NODE
rait_preflight="$(node -e "$rait_preflight_source" "$rait_directory" "$rait_full")"
rait_psql=(psql -X -v ON_ERROR_STOP=1 -q -h "$rait_db_host" -p "$rait_db_port" -U "$rait_db_user")
if [[ "$rait_full" = 1 ]]; then
  "${rait_psql[@]}" -d postgres -c "DO \$owner\$ BEGIN IF EXISTS (SELECT FROM pg_database WHERE datname = '$rait_db_name' AND datdba <> 'postgres'::regrole) THEN RAISE EXCEPTION 'Unsupported disposable database owner'; END IF; END \$owner\$;"
  "${rait_psql[@]}" -d postgres -c "drop database if exists \"$rait_db_name\" with (force)"
  "${rait_psql[@]}" -d postgres -c "create database \"$rait_db_name\" OWNER postgres"
fi
rait_arguments=(-d "$rait_db_name" --single-transaction -c 'SELECT pg_advisory_xact_lock(7007, 1)' -c "$rait_preflight" -c 'SET LOCAL search_path = public, pg_catalog')
while IFS= read -r rait_path; do
  rait_name="$(basename "$rait_path")"
  case "$rait_name" in
    19-rait-priority-pre.sql|19-rait-priority-enforce.sql|19-rait-priority-verify.sql|20-rls-policies.sql) continue ;;
    34-inf-rait-case.sql) rait_arguments+=(-f "$rait_directory/ddl/19-rait-priority-pre.sql") ;;
  esac
  rait_arguments+=(-f "$rait_path")
done < <(find "$rait_directory/ddl" -maxdepth 1 -type f -name '*.sql' | LC_ALL=C sort)
rait_arguments+=(-f "$rait_directory/ddl/20-rls-policies.sql"
  # DDL20 grants its broad baseline after the ordered inventory. Reapply this
  # generated DDL so its applicationAppendOnly revocations are the final,
  # idempotent privilege state both on first application and on reapplication.
  -f "$rait_directory/ddl/21-ops-provisioning.sql"
  -f "$rait_directory/ddl/19-rait-priority-enforce.sql"
  -f "$rait_directory/ddl/19-rait-priority-verify.sql")
"${rait_psql[@]}" "${rait_arguments[@]}"
# psql commits successfully before this line is reached.
echo "apply.sh: done (full=$rait_full db=$rait_db_name)"
{
  "scripts": {
    "stack:start": "bash tools/detran-stack.sh start",
    "stack:stop": "bash tools/detran-stack.sh stop",
    "stack:restart": "bash tools/detran-stack.sh restart",
    "stack:status": "bash tools/detran-stack.sh status",
    "stack:logs": "bash tools/detran-stack.sh logs",
    "stack:build": "bash tools/detran-stack.sh build",
    "stack:db-init": "bash tools/detran-stack.sh db-init",
    "stack:db-reset": "bash tools/detran-stack.sh db-reset"
  }
}
