# SENATRAN mock — full stack for local dev / CI / a dev-only deploy target.
#
#   docker compose up --build          # bring up db + schema/seed + the API
#   curl localhost:3000/health         # -> {"status":"ok","db":"up"}
#
# Siblings (pec, teat) point their SENATRAN base URL at http://localhost:3000.
# This is a mock: never point it at real DENATRAN/SENATRAN data.

services:
  # Postgres. Ephemeral by design — the seed is deterministic, so state is
  # rebuilt on every `up` and there is nothing worth persisting.
  db:
    image: postgres:16
    environment:
      POSTGRES_DB: senatran
      POSTGRES_USER: postgres
      POSTGRES_PASSWORD: postgres
    healthcheck:
      test: ['CMD-SHELL', 'pg_isready -U postgres -d senatran']
      interval: 5s
      timeout: 3s
      retries: 10
    # Uncomment to inspect the database from the host:
    # ports: ['5432:5432']

  # One-shot: apply DDL (in order) + the deterministic sample seed, then exit.
  # --full drops & recreates the schema, so re-running `up` is idempotent.
  migrate:
    image: postgres:16
    depends_on:
      db:
        condition: service_healthy
    environment:
      DB_HOST: db
      DB_PORT: '5432'
      DB_USER: postgres
      DB_PASSWORD: postgres
      DB_NAME: senatran
    volumes:
      - ./database:/database:ro
    entrypoint: ['bash']
    command: ['/database/apply.sh', '--full', '--sample']
    restart: 'no'

  # The NestJS mock API.
  app:
    image: senatran-mock-app:ci
    build:
      context: .
    depends_on:
      db:
        condition: service_healthy
      migrate:
        condition: service_completed_successfully
    environment:
      NODE_ENV: production
      PORT: '3000'
      DATABASE_URL: postgres://postgres:postgres@db:5432/senatran
      AUTH_CERT_SIMULATION: 'on'
    ports:
      - '3000:3000'
    healthcheck:
      test:
        - CMD
        - node
        - -e
        - "fetch('http://127.0.0.1:3000/health').then(r=>r.json()).then(j=>process.exit(j.db==='up'?0:1)).catch(()=>process.exit(1))"
      interval: 10s
      timeout: 3s
      retries: 6
      start_period: 20s
name: DETRAN CI

# NO paths/paths-ignore filters, deliberately: every root *.md (AGENTS.md,
# CLAUDE.md, README.md, CONSTITUTION.md) and everything under docs/ is content
# the devai doctor / docs-governance gates parse, and an absent required check
# is NOT a passing one — a filtered-out required check makes the PR permanently
# unmergeable under branch protection (pec PR #30 lesson; ADR-CI-ECONOMY
# Decision 5.3: never filter content a gate reads).
on:
  workflow_dispatch:
  pull_request:
  push:
    branches:
      - main

permissions:
  contents: read

concurrency:
  group: detran-ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  # Single-source evidence gate (ADR-CI-ECONOMY Decision 7).
  #
  # DEVIATION FROM THE PHASE-0 HANDOFF, RECORDED (W0.1, 2026-08-24): the plan
  # said to call devai's reusable workflow at teat's SHA pin
  # (devai-nyx/devai/.github/workflows/reusable-evidence-gate.yml@5595c05185
  # 7a8e11e23c674cfee0646edeb7d602). That commit is UNREACHABLE upstream
  # (devai main was rewritten for the 1.x ledger model; the adopter-facing
  # reusable-evidence-gate.yml no longer exists at any reachable ref), and
  # teat's own main has already migrated to an IN-REPO evidence-gate job
  # running the installed DEVAI CLI. DETRAN now pins @aarusso-nyx/devai 1.4.5:
  # verify the canonical record/proofs chain; a corrupt/tampered/missing chain FAILS
  # this job, and the foundation job below converts that into a red required
  # check — the gate never silently opens.
  #
  # `evidence_mode` selects the externally attested RC route only when an
  # immutable proof tag exists for the exact candidate tree and no protected
  # control surface changed. Tag presence is only a claim: the separate
  # DEVAI verifier must still publish the required `verified-local-rc` check.
  # A malformed claim therefore blocks; it never silently falls back or opens.
  evidence-gate:
    runs-on: ubuntu-latest
    outputs:
      evidence_mode: ${{ steps.attested.outputs.evidence_mode }}
    steps:
      - uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4
        with:
          ref: ${{ github.event.pull_request.head.sha || github.sha }}
          fetch-depth: 0

      - uses: pnpm/action-setup@f40ffcd9367d9f12939873eb1018b921a783ffaa # v4
        with:
          version: 9.15.0

      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4
        with:
          node-version: '24'
          cache: pnpm

      - name: Install dependencies
        env:
          NODE_AUTH_TOKEN: ${{ secrets.PACKAGES_READ_TOKEN }}
        run: pnpm install --frozen-lockfile

      - name: Verify the DEVAI proof chain (fail-closed)
        run: pnpm exec devai evidence verify --scope chain --repo-root . --show-head --format human

      - name: Select exact-tree attested evidence route
        id: attested
        env:
          EVENT_NAME: ${{ github.event_name }}
          BASE_SHA: ${{ github.event.pull_request.base.sha || github.event.before }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha || github.sha }}
        run: |
          set -euo pipefail
          echo "evidence_mode=false" >> "$GITHUB_OUTPUT"
          case "$EVENT_NAME" in
            pull_request|push) ;;
            *) exit 0 ;;
          esac
          if test -z "$BASE_SHA" || test "$BASE_SHA" = "0000000000000000000000000000000000000000"; then
            exit 0
          fi
          git cat-file -e "${BASE_SHA}^{commit}"
          protected=false
          while IFS= read -r path; do
            case "$path" in
              .github/*|.devai/config/*|law/policy/*|test-tasks.json|package.json|pnpm-lock.yaml|tools/ci/*)
                protected=true
                break
                ;;
            esac
          done < <(git diff --name-only "$BASE_SHA" "$HEAD_SHA")
          if test "$protected" = true; then
            echo "Protected CI control changed; the full remote backend suite is mandatory."
            exit 0
          fi
          tree="$(git rev-parse "${HEAD_SHA}^{tree}")"
          tag="devai-local-evidence/${tree}"
          if test -n "$(git ls-remote --tags origin "refs/tags/${tag}")"; then
            echo "Exact-tree evidence claim found: ${tag}"
            echo "evidence_mode=true" >> "$GITHUB_OUTPUT"
          fi

  foundation:
    runs-on: ubuntu-latest
    needs: evidence-gate
    # Run even when evidence-gate fails so this required check goes RED instead
    # of SKIPPED (a skipped required check would satisfy branch protection —
    # ADR-CI-ECONOMY Decision 2 forbids the gate silently opening). The first
    # step converts a gate failure into a job failure.
    if: ${{ !cancelled() }}
    steps:
      - name: Enforce evidence-gate result
        if: ${{ needs.evidence-gate.result != 'success' }}
        run: |
          echo "::error title=evidence-gate::evidence-gate did not succeed (result: ${{ needs.evidence-gate.result }}) — failing foundation (the gate never silently opens)."
          exit 1

      - uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4

      # pnpm must exist before setup-node's `cache: pnpm` runs. All @stynx-nyx
      # and @aarusso-nyx packages install from GitHub Packages (.npmrc);
      # PACKAGES_READ_TOKEN is a read:packages PAT covering the stynx-nyx and
      # aarusso-nyx orgs — the built-in GITHUB_TOKEN cannot read another org's
      # private packages.
      - uses: pnpm/action-setup@f40ffcd9367d9f12939873eb1018b921a783ffaa # v4
        with:
          version: 9.15.0

      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4
        with:
          node-version: '24'
          cache: pnpm

      - name: Install dependencies
        env:
          NODE_AUTH_TOKEN: ${{ secrets.PACKAGES_READ_TOKEN }}
        run: pnpm install --frozen-lockfile

      - name: Install documentation dependencies
        run: npm ci --prefix docs/site

      # The staged gate set grows with the repo (Phase 2 adds RLS smoke,
      # decorator check, OpenAPI drift, boundary check...). Today `pnpm check`
      # runs the format gate (prettier) and the recursive workspace typecheck.
      - name: Check (format + typecheck)
        run: pnpm check

      - name: Build and link-check documentation
        run: pnpm docs:check

      - name: Audit documentation dependencies
        run: pnpm docs:security

      # CI validates the site but never publishes it. DEVAI reserves Pages
      # publication for an explicitly authorized local external effect.
      - name: DEVAI doctor (blocking)
        run: pnpm exec devai doctor --repo-root . --format human

      - name: Whitespace check
        run: git diff --check

  # Phase-2 unified backend kernel gate (ADR-0005). This is intentionally a
  # separate architecture-named job so database/RLS failures are distinguishable
  # from the general foundation floor. Recommended for branch protection after
  # the orchestrator observes the first green PR run.
  backend-kernel-full:
    name: backend-kernel
    needs: evidence-gate
    if: ${{ !cancelled() && needs.evidence-gate.result == 'success' && needs.evidence-gate.outputs.evidence_mode != 'true' }}
    runs-on: ubuntu-latest
    permissions:
      contents: read
      checks: write
    services:
      postgres:
        image: postgis/postgis@sha256:44126d872ac91993766c341e369c539e8196614321765d36a6f1bab0419a5fa5
        env:
          POSTGRES_DB: detran
          POSTGRES_USER: postgres
          POSTGRES_PASSWORD: postgres
        ports: ['5432:5432']
        options: >-
          --health-cmd "pg_isready -U postgres -d detran"
          --health-interval 10s --health-timeout 5s --health-retries 5
    env:
      DATABASE_URL: postgresql://postgres:postgres@localhost:5432/detran_r7_ctg1_a2
      DETRAN_TEST_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/detran_r7_ctg1_a2
      STYNX_OWNER_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/detran_r7_ctg1_a2
      STYNX_APP_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/detran_r7_ctg1_a2?options=-c%20role%3Drole_app_backend
      STYNX_READER_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/detran_r7_ctg1_a2?options=-c%20role%3Drole_app_backend
      DETRAN_PRIORITY_BASELINE_ADMIN_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/postgres
      DETRAN_SEED_ADMIN_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/postgres
      DETRAN_SEED_SCRATCH_DATABASE_URL: postgresql://postgres:postgres@localhost:5432/detran_r7_ctg1_a2_seed_profiles
      DETRAN_RUNTIME_PROFILE: test
      DETRAN_PRIORITY_UPGRADE_TEST_AUTHORIZED: '1'
      DETRAN_PRIORITY_UPGRADE_BASELINE_AUTHORIZED: '1'
      DETRAN_PRIORITY_UPGRADE_BASELINE_RESET_AUTHORIZED: '1'
      DETRAN_PRIORITY_UPGRADE_RESTORE_AUTHORIZED: '1'
      DETRAN_PRIORITY_UPGRADE_FULL_AUTHORIZED: '1'
      DB_HOST: localhost
      DB_PORT: '5432'
      DB_USER: postgres
      DB_PASSWORD: postgres
      DB_NAME: detran_r7_ctg1_a2
    steps:
      - uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4
        with:
          ref: ${{ github.event.pull_request.head.sha || github.sha }}

      - uses: pnpm/action-setup@f40ffcd9367d9f12939873eb1018b921a783ffaa # v4
        with:
          version: 9.15.0

      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4
        with:
          node-version: '24'
          cache: pnpm

      - name: Install dependencies
        env:
          NODE_AUTH_TOKEN: ${{ secrets.PACKAGES_READ_TOKEN }}
        run: pnpm install --frozen-lockfile

      - name: Run complete remote backend-kernel fallback
        run: pnpm ci:backend-full

      - name: Publish exact-candidate fallback check
        if: always()
        env:
          GH_TOKEN: ${{ github.token }}
          CANDIDATE_SHA: ${{ github.event.pull_request.head.sha || github.sha }}
          JOB_STATUS: ${{ job.status }}
        run: |
          set -euo pipefail
          conclusion=failure
          if test "$JOB_STATUS" = success; then conclusion=success; fi
          jq -n \
            --arg name verified-local-rc \
            --arg head_sha "$CANDIDATE_SHA" \
            --arg conclusion "$conclusion" \
            --arg title "Remote backend fallback" \
            --arg summary "No eligible exact-tree attestation was selected; the complete backend suite ran remotely." \
            '{name:$name,head_sha:$head_sha,status:"completed",conclusion:$conclusion,output:{title:$title,summary:$summary}}' \
            | gh api --method POST "repos/$GITHUB_REPOSITORY/check-runs" --input -
          test "$conclusion" = success

  boat-documents-real:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4

      - uses: pnpm/action-setup@f40ffcd9367d9f12939873eb1018b921a783ffaa # v4
        with:
          version: 9.15.0

      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4
        with:
          node-version: '24'
          cache: pnpm

      - uses: actions/setup-python@a309ff8b426b58ec0e2a45f0f869d46889d02405 # v6.2.0
        with:
          python-version: '3.13.7'

      - name: Install dependencies
        env:
          NODE_AUTH_TOKEN: ${{ secrets.PACKAGES_READ_TOKEN }}
        run: pnpm install --frozen-lockfile

      - name: Install pinned WeasyPrint PDF/A backend
        run: |
          python -m venv /tmp/boat-weasyprint
          /tmp/boat-weasyprint/bin/pip install --require-hashes -r .github/requirements/boat-weasyprint.txt
          /tmp/boat-weasyprint/bin/weasyprint --version | grep -Fx 'WeasyPrint version 70.0'

      - name: Resolve immutable veraPDF image
        run: docker pull verapdf/cli@sha256:20202b4bcc2410a25db1f637c7b461a2e0dda1d97dd8a6df658286b30d56c842

      - name: Prove BOAT production PDF/A-2b path
        env:
          STYNX_VERAPDF_IMAGE: verapdf/cli@sha256:20202b4bcc2410a25db1f637c7b461a2e0dda1d97dd8a6df658286b30d56c842
          WEASYPRINT_BIN: /tmp/boat-weasyprint/bin/weasyprint
        run: pnpm --filter @detran/app test:real

  # ---------------------------------------------------------------------------
  # Activated (W0.2, 2026-08-24): the senatran-mock port landed at
  # ./senatran-mock (245 tests: 119 unit + 14 integration + 112 e2e; 114
  # OpenAPI operations, no drift — verified locally per the W0.2 gate before
  # this job was enabled). Two independent things are exercised here on
  # purpose: (1) the compose/Docker deploy-shaped smoke test (adapted from
  # teat-ci.yml:103-146 and senatran's own compose-smoke.yml, composing from
  # the in-repo ./senatran-mock directory — no pinned sibling checkout, no
  # symlink, per ADR-0003/ADR-0004), and (2) the full ported test suite run
  # directly against a native (non-Docker) Postgres service container, which
  # is faster than exec-ing into the app container and matches how
  # senatran-mock's own pull-request.yml ran tests standalone.
  # ---------------------------------------------------------------------------
  senatran-mock:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4

      # Mirrors senatran's own compose-smoke.yml: buildx with the GitHub
      # Actions layer cache keeps a warm build at ~1-2 min; compose then reuses
      # the loaded senatran-mock-app:ci tag (no --build).
      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@8d2750c68a42422c14e847fe6c8ac0403b4cbd6f # v3

      - name: Build the senatran mock image (GHA layer cache)
        uses: docker/build-push-action@bcafcacb16a39f128d818304e6c9c0c18556b85f # v7.1.0
        with:
          context: senatran-mock
          file: senatran-mock/Dockerfile
          tags: senatran-mock-app:ci
          load: true
          cache-from: type=gha

  [[ -f "$ROOT_DIR/backend/app/dist/main.js" ]] || build_stack
  if [[ "$with_mock" == 1 ]]; then mock_start; fi
  start_backend
  start_frontends
  log "stack started; run '$0 status' for URLs and health"
}

stop_stack() {
  require_runtime
  local index
  for index in "${!FRONTEND_NAMES[@]}"; do
    stop_pid_file "$(frontend_pid_file "${FRONTEND_NAMES[$index]}")"
  done
  stop_pid_file "$(backend_pid_file)"
  mock_stop >/dev/null 2>&1 || true
  if container_running; then
    log "stopping PostGIS container $DB_CONTAINER"
    docker stop "$DB_CONTAINER" >/dev/null
  fi
  log "stack stopped; volumes preserved"
}

status_process() {
  local name="$1"
  local pid_file="$2"
  if pid_running "$pid_file"; then
    echo "$name: running (pid $(<"$pid_file"))"
  else
    echo "$name: stopped"
  fi
}

status_stack() {
  require_runtime
  echo "== detran stack =="
  if container_running; then
    echo "database: running ($DB_CONTAINER, $DB_HOST:$DB_PORT/$DB_NAME)"
  elif container_exists; then
    echo "database: stopped ($DB_CONTAINER)"
  else
    echo "database: not created ($DB_CONTAINER)"
  fi
  status_process backend "$(backend_pid_file)"
  local index
  for index in "${!FRONTEND_NAMES[@]}"; do
    status_process "${FRONTEND_NAMES[$index]}" "$(frontend_pid_file "${FRONTEND_NAMES[$index]}")"
  done
  echo
  echo "== SENATRAN mock =="
  mock_status || true
  echo
  echo "== URLs =="
  echo "backend:  http://127.0.0.1:$BACKEND_PORT/healthz"
  echo "mock:     http://127.0.0.1:3000/health"
  echo "portal:   http://127.0.0.1:4200"
  echo "rait:     http://127.0.0.1:4201"
  echo "dashboard:http://127.0.0.1:4202"
  echo "teat:     http://127.0.0.1:4203"
}

logs_stack() {
  local service="${1:-}"
  [[ -n "$service" ]] || die "usage: $0 logs <db|mock|backend|portal|rait|dashboard|teat>"
  case "$service" in
    db) docker logs --follow "$DB_CONTAINER" ;;
    mock) docker compose -p "$MOCK_PROJECT" -f "$MOCK_COMPOSE_FILE" logs --follow --tail=100 ;;
    backend|portal|rait|dashboard|teat)
      tail -f "$LOG_DIR/$service.log"
      ;;
    *) die "unknown service: $service" ;;
  esac
}

command="${1:-help}"
shift || true
case "$command" in
  start) start_stack "$@" ;;
  stop) [[ $# -eq 0 ]] || die "stop accepts no options"; stop_stack ;;
  restart) stop_stack; start_stack "$@" ;;
  status) [[ $# -eq 0 ]] || die "status accepts no options"; status_stack ;;
  logs) logs_stack "$@" ;;
  build) [[ $# -eq 0 ]] || die "build accepts no options"; require_command pnpm; build_stack ;;
  db-init) [[ $# -eq 0 ]] || die "db-init accepts no options"; require_runtime; init_database ;;
  db-reset) [[ $# -eq 0 ]] || die "db-reset accepts no options"; require_runtime; reset_database ;;
  help|-h|--help) usage ;;
  *) usage; die "unknown command: $command" ;;
esac
