import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';
import test from 'node:test';

const root = resolve(new URL('.', import.meta.url).pathname, '../..');
const stackSource = readFileSync(join(root, 'tools/detran-stack.sh'), 'utf8');
const applySource = readFileSync(
  join(root, 'backend/database/apply.sh'),
  'utf8',
);
const ciSource = readFileSync(join(root, '.github/workflows/ci.yml'), 'utf8');
const proxy = JSON.parse(
  readFileSync(join(root, 'tools/detran-stack.proxy.json'), 'utf8'),
);
const newDatabase = ['detran', 'local', 'stack'].join('_');
const fullAuthorization = [
  'DETRAN',
  'LOCAL',
  'STACK',
  'FULL',
  'AUTHORIZED',
].join('_');

function makeStub(bin, name, body) {
  const path = join(bin, name);
  writeFileSync(path, `#!/usr/bin/env bash\nset -euo pipefail\n${body}\n`, {
    mode: 0o755,
  });
}

function run(command, args, env = {}, { allowDockerComposeConfig = false } = {}) {
  const stateDir = mkdtempSync(join(tmpdir(), 'detran-stack-revision-state-'));
  const bin = mkdtempSync(join(tmpdir(), 'detran-stack-revision-stubs-'));
  const dockerPath = process.env.PATH.split(':')
    .map((entry) => join(entry, 'docker'))
    .find((candidate) => existsSync(candidate));
  const dockerBody = allowDockerComposeConfig && dockerPath
    ? `if [[ "$*" == *"compose"*"config"* ]]; then exec ${dockerPath@Q} "$@"; fi\nexit 97`
    : 'exit 97';
  makeStub(bin, 'docker', dockerBody);
  makeStub(bin, 'pnpm', 'exit 97');
  makeStub(bin, 'psql', 'exit 97');
  try {
    return spawnSync(command, args, {
      cwd: root,
      encoding: 'utf8',
      env: {
        ...process.env,
        DETRAN_STACK_STATE_DIR: stateDir,
        PATH: `${bin}:${process.env.PATH}`,
        ...env,
      },
    });
  } finally {
    rmSync(stateDir, { recursive: true, force: true });
    rmSync(bin, { recursive: true, force: true });
  }
}

function assertNoSecrets(value) {
  assert.doesNotMatch(
    value,
    /(?:password|token|secret|api[_-]?key)\s*[:=]\s*[^null\s}]+/i,
  );
  assert.doesNotMatch(value, /:\/\/[^/\s:@]+:[^@\s]+@/);
}

