test('dado o mock SENATRAN quando compose é resolvido então o override publica somente loopback', () => {
  const override = join(root, 'tools/stack/senatran-mock.compose.yml');
  assert.ok(existsSync(override));
  const result = run(
    'docker',
    [
      'compose',
      '-f',
      'senatran-mock/docker-compose.yml',
      '-f',
      override,
      'config',
      '--format',
      'json',
    ],
    {},
    { allowDockerComposeConfig: true },
  );
  assert.equal(
    result.status,
    0,
    result.stderr || 'Compose CLI is unavailable for offline config validation',
  );
  const config = JSON.parse(result.stdout);
  const ports = config.services.app.ports;
  assert.equal(ports.length, 1);
  const port = ports[0];
  if (typeof port === 'string') {
    assert.equal(port, '127.0.0.1:3000:3000');
  } else {
    assert.equal(port.host_ip, '127.0.0.1');
    assert.equal(port.published, 3000);
    assert.equal(port.target, 3000);
  }
  assert.match(stackSource, /2\.24\.4|compose.*version/i);
});

